import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

import type { AuditActionDefinition, AuditActor, AuditEntity, AuditFilter, AuditOutcome, AuditRecord } from '@babulvaibhav/egradx-client'
import { humanize, shortId, tone } from '../egradx-ui'

/** The action catalog by action, for labels. */
export type ActionCatalog = Map<string, AuditActionDefinition>

export const OUTCOMES: AuditOutcome[] = ['SUCCESS', 'FAILURE', 'DENIED']

export const OUTCOME_LABEL: Record<AuditOutcome, string> = { SUCCESS: 'Succeeded', FAILURE: 'Failed', DENIED: 'Refused' }

export const OUTCOME_TONE: Record<AuditOutcome, string> = { SUCCESS: tone.success, FAILURE: tone.danger, DENIED: tone.warning }

/**
 * The audit log's filter as a form (and an address bar) holds it: every field a string, '' for "any". Dates are
 * `YYYY-MM-DD`, local days.
 */
export interface AuditLogFilter {
  q: string
  category: string
  action: string
  outcome: string
  from: string
  to: string
  correlationId: string
  actorId: string
  /** Shown on the "By …" chip; not searched. */
  actorName: string
  entityType: string
  entityId: string
  /** Shown on the entity chip; not searched. */
  entityName: string
}

export const EMPTY_FILTER: AuditLogFilter = {
  q: '', category: '', action: '', outcome: '', from: '', to: '', correlationId: '', actorId: '', actorName: '', entityType: '', entityId: '', entityName: '',
}

/** What the API is asked for. */
export function toAuditFilter(filter: AuditLogFilter): AuditFilter {
  return {
    q: filter.q || undefined,
    category: filter.category || undefined,
    action: filter.action || undefined,
    outcome: (filter.outcome || undefined) as AuditOutcome | undefined,
    from: startOfDay(filter.from),
    to: endOfDay(filter.to),
    correlationId: filter.correlationId || undefined,
    actorId: filter.actorId || undefined,
    entityType: filter.entityType || undefined,
    entityId: filter.entityId || undefined,
  }
}

/** "Edited a product" from the catalog; otherwise the action's last segments, readable. */
export function actionLabel(action: string, catalog: ActionCatalog | undefined): string {
  const known = catalog?.get(action)?.description
  if (known) return known
  const [, ...rest] = action.split('.')
  return humanize(rest.join(' ') || action)
}

/** An action category as people read it. Add your application's own. */
export function categoryLabel(category: string): string {
  const known: Record<string, string> = { auth: 'Sign-in and access', notification: 'Notifications', audit: 'Audit trail' }
  return known[category] ?? humanize(category)
}

export function actorName(actor: AuditActor): string {
  if (actor.type === 'SYSTEM') return 'System'
  if (actor.name) return actor.name
  if (actor.label) return actor.label
  if (actor.type === 'ANONYMOUS') return 'Someone not signed in'
  if (actor.id) return `User #${shortId(actor.id)}`
  return 'Unknown'
}

export function entityText(entity: AuditEntity): string | null {
  if (!entity.type) return null
  const what = humanize(entity.type)
  if (entity.label) return `${what} · ${entity.label}`
  if (entity.id) return `${what} #${entity.id.length > 12 ? shortId(entity.id) : entity.id}`
  return what
}

/** The value at a dotted path, as the API names changed fields (`address.city`). */
function valueAt(state: Record<string, unknown> | null, path: string): unknown {
  let current: unknown = state
  for (const segment of path.split('.')) {
    if (current === null || typeof current !== 'object' || Array.isArray(current)) return undefined
    current = (current as Record<string, unknown>)[segment]
  }
  return current
}

export function displayValue(value: unknown): string {
  if (value === undefined || value === null || value === '') return '—'
  if (typeof value === 'string') return value
  if (typeof value === 'number' || typeof value === 'boolean') return String(value)
  return JSON.stringify(value)
}

/** The rows a change is shown as: what changed when there is a before and an after, else every field. */
export function changeRows(record: AuditRecord): { field: string; before: unknown; after: unknown }[] {
  if (record.before && record.after && record.changedFields) {
    return record.changedFields.map((field) => ({ field, before: valueAt(record.before, field), after: valueAt(record.after, field) }))
  }
  const state = record.after ?? record.before
  if (!state) return []
  return Object.keys(state)
    .sort()
    .map((field) => ({ field, before: record.before?.[field], after: record.after?.[field] }))
}

/** A date input's `YYYY-MM-DD` as the start of that local day. */
function startOfDay(date: string): string | undefined {
  return date ? new Date(`${date}T00:00:00`).toISOString() : undefined
}

/** The start of the local day after, so the range includes the whole of `date`. */
function endOfDay(date: string): string | undefined {
  if (!date) return undefined
  const next = new Date(`${date}T00:00:00`)
  next.setDate(next.getDate() + 1)
  return next.toISOString()
}

import type { AuditRecord } from '@babulvaibhav/egradx-client'
import { cn } from '@/lib/utils'
import { changeRows, displayValue } from './audit-format'

/** A record's change as a table: field, before, after; only what changed, when both are known. */
export function AuditChanges({ record, className }: { record: AuditRecord; className?: string }) {
  const rows = changeRows(record)
  if (rows.length === 0) return null
  const showBefore = record.before !== null
  const showAfter = record.after !== null
  return (
    <div className={cn('overflow-x-auto rounded-md border', className)}>
      <table className="w-full text-xs">
        <thead className="bg-muted/50 text-muted-foreground">
          <tr>
            <th className="px-3 py-2 text-left font-medium">Field</th>
            {showBefore && <th className="px-3 py-2 text-left font-medium">Before</th>}
            {showAfter && <th className="px-3 py-2 text-left font-medium">After</th>}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.field} className="border-t align-top">
              <td className="text-muted-foreground px-3 py-2 font-mono whitespace-nowrap">{row.field}</td>
              {showBefore && (
                <td className={cn('px-3 py-2 break-all', showAfter && 'text-destructive/90 line-through decoration-1')}>{displayValue(row.before)}</td>
              )}
              {showAfter && <td className="px-3 py-2 break-all">{displayValue(row.after)}</td>}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

'use client'

import type { ReactNode } from 'react'
import { History, UserSearch } from 'lucide-react'
import type { AuditRecord } from '@babulvaibhav/egradx-client'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet'
import { formatDateTime, humanize } from '../egradx-ui'
import { AuditChanges } from './audit-changes'
import { OUTCOME_LABEL, OUTCOME_TONE, actionLabel, actorName, displayValue, type ActionCatalog } from './audit-format'

interface AuditRecordSheetProps {
  record: AuditRecord | null
  catalog: ActionCatalog
  onOpenChange: (open: boolean) => void
  /** Offers everything recorded about the record's entity. */
  onShowHistory?: (record: AuditRecord) => void
  /** Offers everything this person did. */
  onShowActor?: (record: AuditRecord) => void
}

function Fact({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="grid grid-cols-[8rem_1fr] gap-3 py-1.5 text-sm">
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="min-w-0 break-words">{children}</dd>
    </div>
  )
}

/** One record in full: what, who, on what, what changed, and from where. */
export function AuditRecordSheet({ record, catalog, onOpenChange, onShowHistory, onShowActor }: AuditRecordSheetProps) {
  return (
    <Sheet open={!!record} onOpenChange={onOpenChange}>
      <SheetContent className="gap-0 overflow-y-auto sm:max-w-xl">
        {record && (
          <>
            <SheetHeader>
              <SheetTitle className="flex flex-wrap items-center gap-2">
                {actionLabel(record.action, catalog)}
                <Badge variant="outline" className={OUTCOME_TONE[record.outcome]}>
                  {OUTCOME_LABEL[record.outcome]}
                </Badge>
              </SheetTitle>
              <SheetDescription className="font-mono text-xs">{record.action}</SheetDescription>
            </SheetHeader>
            <div className="space-y-5 px-4 pb-6">
              <dl>
                <Fact label="When">{formatDateTime(record.occurredAt)}</Fact>
                <Fact label="Who">
                  {actorName(record.actor)}
                  {record.actor.label && record.actor.name && record.actor.label !== record.actor.name && (
                    <span className="text-muted-foreground"> ({record.actor.label})</span>
                  )}
                </Fact>
                {record.entity.type && (
                  <Fact label={humanize(record.entity.type)}>
                    {record.entity.label ?? '—'}
                    {record.entity.id && <span className="text-muted-foreground ml-2 font-mono text-xs">{record.entity.id}</span>}
                  </Fact>
                )}
                {record.reason && (
                  <Fact label="Reason">
                    <span className="font-mono text-xs">{record.reason}</span>
                  </Fact>
                )}
                {record.organizationName && <Fact label="Organization">{record.organizationName}</Fact>}
              </dl>

              {(onShowHistory || onShowActor) && (
                <div className="flex flex-wrap gap-2">
                  {onShowHistory && record.entity.type && record.entity.id && (
                    <Button variant="outline" size="sm" onClick={() => onShowHistory(record)}>
                      <History /> History of this {humanize(record.entity.type).toLowerCase()}
                    </Button>
                  )}
                  {onShowActor && record.actor.id && (
                    <Button variant="outline" size="sm" onClick={() => onShowActor(record)}>
                      <UserSearch /> Everything by {actorName(record.actor)}
                    </Button>
                  )}
                </div>
              )}

              {(record.before || record.after) && (
                <section className="space-y-2">
                  <h3 className="text-sm font-medium">{record.before && record.after ? 'What changed' : record.after ? 'Created as' : 'As it was'}</h3>
                  <AuditChanges record={record} />
                </section>
              )}

              {record.details && Object.keys(record.details).length > 0 && (
                <section className="space-y-2">
                  <h3 className="text-sm font-medium">Details</h3>
                  <dl className="rounded-md border px-3 py-1">
                    {Object.entries(record.details).map(([key, value]) => (
                      <Fact key={key} label={humanize(key.replace(/([a-z])([A-Z])/g, '$1_$2'))}>
                        <span className="font-mono text-xs">{displayValue(value)}</span>
                      </Fact>
                    ))}
                  </dl>
                </section>
              )}

              <Separator />
              <dl className="text-muted-foreground">
                <Fact label="Address">{record.clientAddress ?? '—'}</Fact>
                <Fact label="Browser">
                  <span className="text-xs">{record.userAgent ?? '—'}</span>
                </Fact>
                <Fact label="Request id">
                  <span className="font-mono text-xs">{record.requestId ?? '—'}</span>
                </Fact>
                <Fact label="Trace id">
                  <span className="font-mono text-xs">{record.traceId ?? '—'}</span>
                </Fact>
                <Fact label="Record id">
                  <span className="font-mono text-xs">{record.id}</span>
                </Fact>
              </dl>
            </div>
          </>
        )}
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useMemo, useState } from 'react'
import { History } from 'lucide-react'
import { useAuditActions, useAuditTimeline } from '@babulvaibhav/egradx-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState, ErrorState } from '../egradx-common'
import { formatDateTime } from '../egradx-ui'
import { AuditChanges } from './audit-changes'
import { OUTCOME_LABEL, OUTCOME_TONE, actionLabel, actorName, type ActionCatalog } from './audit-format'

interface AuditTimelineProps {
  /** As the application records it: product, order, user… */
  entityType: string
  entityId: string
  /** What the sheet calls it, e.g. the product's name. */
  title: string
  open: boolean
  onOpenChange: (open: boolean) => void
  /** The platform's records rather than the organization's (needs the platform audit permission). */
  platform?: boolean
}

/** Everything recorded about one thing, newest first, each with what changed. Loaded only while open. */
export function AuditTimeline({ entityType, entityId, title, open, onOpenChange, platform }: AuditTimelineProps) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="gap-0 overflow-y-auto sm:max-w-xl">
        <SheetHeader>
          <SheetTitle>History — {title}</SheetTitle>
          <SheetDescription>Every recorded change, newest first. Records can't be edited or removed.</SheetDescription>
        </SheetHeader>
        {open && <TimelineBody entityType={entityType} entityId={entityId} platform={platform} />}
      </SheetContent>
    </Sheet>
  )
}

function TimelineBody({ entityType, entityId, platform }: { entityType: string; entityId: string; platform?: boolean }) {
  const actions = useAuditActions({ platform })
  const catalog: ActionCatalog = useMemo(() => new Map((actions.data ?? []).map((definition) => [definition.action, definition])), [actions.data])
  const timeline = useAuditTimeline(entityType, entityId, { platform })

  return (
    <div className="px-4 pb-6">
      {timeline.loading ? (
        <div className="space-y-3">
          <Skeleton className="h-16 w-full" />
          <Skeleton className="h-16 w-full" />
        </div>
      ) : timeline.error ? (
        <ErrorState error={timeline.error} onRetry={() => void timeline.reload()} />
      ) : timeline.items.length === 0 ? (
        <EmptyState icon={<History />} title="Nothing recorded yet" description="Changes will appear here as they happen." />
      ) : (
        <ol className="relative ml-1 space-y-5 border-l pl-5">
          {timeline.items.map((record) => (
            <li key={record.id} className="space-y-2">
              <span className="bg-primary absolute -left-[5px] mt-1.5 size-2.5 rounded-full" />
              <div className="flex flex-wrap items-center gap-2 text-sm">
                <span className="font-medium">{actionLabel(record.action, catalog)}</span>
                {record.outcome !== 'SUCCESS' && (
                  <Badge variant="outline" className={OUTCOME_TONE[record.outcome]}>
                    {OUTCOME_LABEL[record.outcome]}
                  </Badge>
                )}
              </div>
              <p className="text-muted-foreground text-xs">
                {formatDateTime(record.occurredAt)} · {actorName(record.actor)}
              </p>
              {record.before && record.after && <AuditChanges record={record} />}
            </li>
          ))}
        </ol>
      )}
      {timeline.hasMore && (
        <div className="mt-5 flex justify-center">
          <Button variant="outline" size="sm" onClick={() => void timeline.loadMore()} disabled={timeline.loadingMore}>
            {timeline.loadingMore ? 'Loading…' : 'Load older'}
          </Button>
        </div>
      )}
    </div>
  )
}

/**
 * "History" on a detail page: the audit timeline of that one thing. Show it only to those who may read the trail
 * (e.g. inside `<Can authority="egradx.audit.read">`).
 */
export function AuditHistoryButton({ entityType, entityId, title }: { entityType: string; entityId: string; title: string }) {
  const [open, setOpen] = useState(false)
  return (
    <>
      <Button variant="outline" onClick={() => setOpen(true)}>
        <History /> History
      </Button>
      <AuditTimeline entityType={entityType} entityId={entityId} title={title} open={open} onOpenChange={setOpen} />
    </>
  )
}

'use client'

import { useMemo, useState } from 'react'
import { Download, FilterX, RefreshCw, ScrollText, X } from 'lucide-react'
import { useAuditActions, useAuditExport, useAuditLog } from '@babulvaibhav/egradx-react'
import type { AuditRecord } from '@babulvaibhav/egradx-client'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { cn } from '@/lib/utils'
import { EmptyState, ErrorState, SearchBox } from '../egradx-common'
import { errorText, formatDateTime, humanize, ignoreNotice, type Notify } from '../egradx-ui'
import { AuditRecordSheet } from './audit-record-sheet'
import { AuditTimeline } from './audit-timeline'
import {
  EMPTY_FILTER,
  OUTCOMES,
  OUTCOME_LABEL,
  OUTCOME_TONE,
  actionLabel,
  actorName,
  categoryLabel,
  entityText,
  toAuditFilter,
  type ActionCatalog,
  type AuditLogFilter,
} from './audit-format'

const ALL = 'all'

export interface AuditLogProps {
  /**
   * The filter, when the application keeps it (in the address, so a search can be shared); with `onFilterChange`.
   * Without it the component keeps its own.
   */
  filter?: AuditLogFilter
  onFilterChange?: (filter: AuditLogFilter) => void
  /** Every organization's records (needs the platform audit permission). Default: the person's organization. */
  platform?: boolean
  /** Export results, for your toasts. */
  onNotify?: Notify
  className?: string
}

function saveFile(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.click()
  URL.revokeObjectURL(url)
}

/**
 * The audit trail: search and filters, newest first a page at a time, each record in full, a thing's history, and
 * the CSV export. Records can't be edited or deleted.
 */
export function AuditLog({ filter: controlled, onFilterChange, platform, onNotify = ignoreNotice, className }: AuditLogProps) {
  const [own, setOwn] = useState<AuditLogFilter>(EMPTY_FILTER)
  const filter = controlled ?? own
  const setFilter = (patch: Partial<AuditLogFilter>) => {
    const next = { ...filter, ...patch }
    if (onFilterChange) onFilterChange(next)
    if (!controlled) setOwn(next)
  }

  const query = useMemo(() => toAuditFilter(filter), [filter])
  const events = useAuditLog({ filter: query, platform })
  const exporter = useAuditExport({ platform })
  const actions = useAuditActions({ platform })
  const catalog: ActionCatalog = useMemo(() => new Map((actions.data ?? []).map((definition) => [definition.action, definition])), [actions.data])
  const [viewing, setViewing] = useState<AuditRecord | null>(null)
  const [history, setHistory] = useState<{ entityType: string; entityId: string; title: string } | null>(null)

  const categories = useMemo(() => [...new Set((actions.data ?? []).map((action) => action.category))].sort(), [actions.data])
  const actionOptions = useMemo(
    () => (actions.data ?? []).filter((action) => !filter.category || action.category === filter.category).sort((a, b) => a.description.localeCompare(b.description)),
    [actions.data, filter.category],
  )
  const anyFilter = (Object.keys(EMPTY_FILTER) as (keyof AuditLogFilter)[]).some((key) => filter[key])

  const exportCsv = () =>
    exporter.run(query).then(
      ({ blob, filename, truncated, rowLimit }) => {
        saveFile(blob, filename)
        onNotify(
          truncated
            ? { tone: 'warning', title: `Only the newest ${rowLimit.toLocaleString()} records were exported`, description: 'More records match. Narrow the dates to export the rest.' }
            : { tone: 'success', title: 'Audit records exported' },
        )
      },
      (error) => onNotify({ tone: 'error', title: 'Could not export', description: errorText(error) }),
    )

  return (
    <div className={cn('space-y-4', className)}>
      <div className="bg-card space-y-4 rounded-xl border p-4">
        <div className="flex flex-wrap items-end gap-3">
          <SearchBox value={filter.q} onChange={(q) => setFilter({ q })} placeholder="Search names, ids, actions…" />
          <Select value={filter.category || ALL} onValueChange={(category) => setFilter({ category: category === ALL ? '' : category, action: '' })}>
            <SelectTrigger className="w-48" aria-label="Area">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>All areas</SelectItem>
              {categories.map((category) => (
                <SelectItem key={category} value={category}>
                  {categoryLabel(category)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={filter.action || ALL} onValueChange={(action) => setFilter({ action: action === ALL ? '' : action })}>
            <SelectTrigger className="w-60" aria-label="Action">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>All actions</SelectItem>
              {actionOptions.map((action) => (
                <SelectItem key={action.action} value={action.action}>
                  {action.description}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={filter.outcome || ALL} onValueChange={(outcome) => setFilter({ outcome: outcome === ALL ? '' : outcome })}>
            <SelectTrigger className="w-40" aria-label="Outcome">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>Any outcome</SelectItem>
              {OUTCOMES.map((outcome) => (
                <SelectItem key={outcome} value={outcome}>
                  {OUTCOME_LABEL[outcome]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button variant="outline" className="ml-auto" onClick={() => void exportCsv()} disabled={exporter.pending}>
            <Download /> {exporter.pending ? 'Exporting…' : 'Export CSV'}
          </Button>
        </div>
        <div className="flex flex-wrap items-end gap-3">
          <div className="space-y-1.5">
            <Label htmlFor="audit-from" className="text-muted-foreground text-xs">
              From
            </Label>
            <Input id="audit-from" type="date" className="w-40" value={filter.from} onChange={(event) => setFilter({ from: event.target.value })} />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="audit-to" className="text-muted-foreground text-xs">
              To
            </Label>
            <Input id="audit-to" type="date" className="w-40" value={filter.to} onChange={(event) => setFilter({ to: event.target.value })} />
          </div>
          <SearchBox value={filter.correlationId} onChange={(correlationId) => setFilter({ correlationId })} placeholder="Request or trace id" className="sm:w-60" />
          <div className="ml-auto flex gap-2">
            <Button variant="ghost" size="sm" onClick={() => void events.reload()} disabled={events.loading}>
              <RefreshCw /> Refresh
            </Button>
            {anyFilter && (
              <Button variant="ghost" size="sm" onClick={() => setFilter(EMPTY_FILTER)}>
                <FilterX /> Clear filters
              </Button>
            )}
          </div>
        </div>
        {(filter.actorId || filter.entityId) && (
          <div className="flex flex-wrap gap-2">
            {filter.actorId && (
              <Badge variant="secondary" className="gap-1 pr-1">
                By {filter.actorName || 'one person'}
                <button type="button" aria-label="Remove" onClick={() => setFilter({ actorId: '', actorName: '' })}>
                  <X className="size-3" />
                </button>
              </Badge>
            )}
            {filter.entityId && (
              <Badge variant="secondary" className="gap-1 pr-1">
                {humanize(filter.entityType)}: {filter.entityName || filter.entityId}
                <button type="button" aria-label="Remove" onClick={() => setFilter({ entityType: '', entityId: '', entityName: '' })}>
                  <X className="size-3" />
                </button>
              </Badge>
            )}
          </div>
        )}
      </div>

      {events.loading ? (
        <Skeleton className="h-64 w-full" />
      ) : events.error && events.items.length === 0 ? (
        <ErrorState error={events.error} onRetry={() => void events.reload()} />
      ) : events.items.length === 0 ? (
        <EmptyState
          icon={<ScrollText />}
          title={anyFilter ? 'No records match these filters' : 'Nothing recorded yet'}
          description={anyFilter ? undefined : 'Sign-ins, access changes and changes to your data appear here as they happen.'}
        />
      ) : (
        <div className="space-y-4">
          <div className="bg-card rounded-xl border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>When</TableHead>
                  <TableHead>What</TableHead>
                  <TableHead>Who</TableHead>
                  <TableHead className="hidden md:table-cell">On</TableHead>
                  <TableHead className="hidden lg:table-cell">Address</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {events.items.map((record) => (
                  <TableRow key={record.id} className="cursor-pointer" onClick={() => setViewing(record)}>
                    <TableCell className="text-muted-foreground whitespace-nowrap tabular-nums">{formatDateTime(record.occurredAt)}</TableCell>
                    <TableCell>
                      <div className="flex flex-wrap items-center gap-2">
                        <span>{actionLabel(record.action, catalog)}</span>
                        {record.outcome !== 'SUCCESS' && (
                          <Badge variant="outline" className={OUTCOME_TONE[record.outcome]}>
                            {OUTCOME_LABEL[record.outcome]}
                            {record.reason && `: ${humanize(record.reason.replace(/^[A-Z]+_/, ''))}`}
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="max-w-48 truncate">{actorName(record.actor)}</TableCell>
                    <TableCell className="text-muted-foreground hidden max-w-64 truncate md:table-cell">{entityText(record.entity) ?? '—'}</TableCell>
                    <TableCell className="text-muted-foreground hidden font-mono text-xs lg:table-cell">{record.clientAddress ?? '—'}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          <div className="text-muted-foreground flex items-center justify-between text-sm">
            <span>
              {events.items.length} record{events.items.length === 1 ? '' : 's'} shown, newest first
            </span>
            {events.hasMore && (
              <Button variant="outline" size="sm" onClick={() => void events.loadMore()} disabled={events.loadingMore}>
                {events.loadingMore ? 'Loading…' : 'Load older'}
              </Button>
            )}
          </div>
        </div>
      )}

      <AuditRecordSheet
        record={viewing}
        catalog={catalog}
        onOpenChange={(open) => !open && setViewing(null)}
        onShowHistory={(record) => {
          setViewing(null)
          setHistory({
            entityType: record.entity.type!,
            entityId: record.entity.id!,
            title: record.entity.label ?? `${humanize(record.entity.type)} #${record.entity.id}`,
          })
        }}
        onShowActor={(record) => {
          setViewing(null)
          setFilter({ actorId: record.actor.id!, actorName: actorName(record.actor) })
        }}
      />
      {history && (
        <AuditTimeline
          entityType={history.entityType}
          entityId={history.entityId}
          title={history.title}
          platform={platform}
          open
          onOpenChange={(open) => !open && setHistory(null)}
        />
      )}
    </div>
  )
}
